// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant ORIGINAL_CEO = 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != ORIGINAL_CEO);
        // Record the current ceoAddress before the call
        address ceoBefore = c.ceoAddress();
        // Attempt to call DrugDealer as a non-CEO
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        // The call should revert for any non-CEO caller, so success should be false
        assertTrue(!success);
        // Also verify that ceoAddress was not changed
        address ceoAfter = c.ceoAddress();
        assertTrue(ceoAfter == ceoBefore);
    }
}

